document.querySelector('#download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,text:input.value})],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='notes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
