const load=async id=>{const mine=++generation;doc.textContent='Loading';try{const response=await fetch('/docs/'+id);if(!response.ok)throw Error('HTTP '+response.status);const text=await response.text();doc.dataset.completed=id;if(mine===generation)doc.textContent=text}catch(e){if(mine===generation)doc.textContent=String(e)}};
