async function playwrightExample(u,folder){const config=`import {defineConfig} from '@playwright/test';export default defineConfig({testDir:'.',testMatch:'lesson.spec.mjs',fullyParallel:true,retries:${u.day===24?'2':'0'},reporter:[['list'],['html',{open:'never'}]],use:{baseURL:'http://127.0.0.1:4179',browserName:'chromium',viewport:{width:1000,height:800},locale:'en-US',timezoneId:'UTC',colorScheme:'light',reducedMotion:'reduce',trace:'retain-on-failure',screenshot:'only-on-failure'},webServer:{command:'node server.mjs',url:'http://127.0.0.1:4179',reuseExistingServer:false}});\n`;
let spec=`import {test${u.day===22?' as base':''},expect} from '@playwright/test';import {readFile} from 'node:fs/promises';\n`;
if(u.day===22)spec+=`const test=base.extend({page:async({page},use)=>{await page.goto('/');await page.evaluate(()=>localStorage.clear());await page.reload();await use(page);await page.evaluate(()=>localStorage.clear())}});\n`;
spec+=`test.beforeEach(async({page})=>{await page.goto('/')});\ntest(${JSON.stringify(u.title)},async({page,browser},testInfo)=>{\n${pwBodies[u.day]}\n});\n`;
const files={'lesson.spec.mjs':spec,'fixture.html':fixture,'server.mjs':server,'playwright.config.mjs':config};if(u.day===27)files['ci.yml']=`name: Lesson E2E\non: [push, pull_request]\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 22\n      - run: npm ci\n      - run: npx playwright install --with-deps chromium\n      - run: npx playwright test\n      - uses: actions/upload-artifact@v4\n        if: always()\n        with:\n          name: playwright-report\n          path: playwright-report/\n`;
for(const [p,s] of Object.entries(files)){files[p]=await formatGeneratedText(path.join(folder,p),s);await save(path.join(folder,p),files[p]);}return {source:externalPreview(u,files,'Standalone fixture tests (not tests of the production Frontory UI). Copy this lesson folder into an empty test project. Run npm init -y; npm install -D @playwright/test; npx playwright install chromium; npx playwright test. Config starts fixture HTTP server on 127.0.0.1:4179. For visual units, create and review baselines with --update-snapshots. Run npx playwright show-trace <trace.zip> for retained failures. CI template assumes these files are project root and a committed package-lock.json.'),files:Object.keys(files)}}

