 const curriculum=JSON.parse(fs.readFileSync(path.join(base,'content/curricula',series+'.json'),'utf8'));const mapping={};
 const legacyIds=new Set(JSON.parse(fs.readFileSync('content/catalog-v2.json','utf8')).units.filter(unit=>unit.seriesId===series).map(unit=>unit.id))
 Object.assign(mapping,Object.fromEntries(Object.entries(JSON.parse(fs.readFileSync('content/examples/'+series+'.json','utf8'))).filter(([id])=>legacyIds.has(id))))
 for(const u of curriculum.units.filter(u=>u.id.includes('-step-'))){const folder=path.join(base,'src/labs',u.id);let source,files=[];if(series==='gsap')source=gsExample(u);if(series==='motion')source=motionExample(u);if(series==='web-workers')source=workersExample(u);if(series==='offscreen-canvas')source=offscreenExample(u);if(series==='webassembly')({source,files}=await wasmExample(u,folder));if(series==='playwright')({source,files}=await playwrightExample(u,folder));const localized=await localizeExampleSource(u.id,source,u.id==='gsap-step-02'?{[JSON.parse(source.split('root.innerHTML=')[1].split(';\n')[0])]:'markup','fromTo supplies both endpoints; initial styles stay unchanged until Run':'result'}:{},u.id==='gsap-step-02'?{}:{messagesMarker:'/* ENGINEERING_MESSAGES */'});await save(path.join(folder,'example.js'),localized.source);mapping[u.id]={...(localized.readingSource?{readingSource:localized.readingSource}:{}),mode:files.length?'external':'browser',note:reviewedNotes[u.id]??(files.length?(series==='webassembly'?'Standalone WAT + Node assertions; iframe CSP blocks Wasm compilation.':'Runnable standalone Playwright spec and HTTP fixture; preview does not run tests.'):(/[가-힣]/.test(u.title)?u.title+' 실험입니다. 직접 조작할 수 있으며 사용한 자원을 정리합니다.':'Interactive '+u.title+' experiment with resource cleanup.')),...(files.length?{files:files.map(f=>'src/labs/'+u.id+'/'+f)}:{})};}
 await save(path.join(base,'content/examples',series+'.json'),JSON.stringify(mapping,null,2)+'\n');console.log(series,Object.keys(mapping).length);await writeCompanionGuidance('scripts/generate-engineering-examples.mjs',series);
